api.script:
var page = db.selectOne("""
    SELECT id, slug, name, status, content, template_id, short_code,
           pv_count, uv_count, publish_time
    FROM landing_page WHERE id = #{id}
    """);
if (page == null) {
    return response.json(404, "页面不存在", null);
}
return page;

var page = db.selectOne("""
    SELECT id, slug, name, content, status
    FROM landing_page
    WHERE slug = #{slug} AND status = 10
    """);
if (page == null) {
    return response.json(404, "页面不存在或已下线", null);
}
return page;

var body = request.body();
if (body.id == null) {
    var id = db.insert("""
        INSERT INTO landing_page(slug, name, status, content, template_id, pv_count, uv_count)
        VALUES(#{body.slug}, #{body.name}, 0, #{body.content}, #{body.templateId}, 0, 0)
        """);
    return { id: id };
} else {
    var affected = db.update("""
        UPDATE landing_page
        SET name = #{body.name}, content = #{body.content}, template_id = #{body.templateId}
        WHERE id = #{body.id} AND status = 0
        """);
    if (affected == 0) {
        return response.json(400, "仅草稿态可编辑", null);
    }
    return { id: body.id };
}

var body = request.body();
var page = db.selectOne("SELECT id, slug FROM landing_page WHERE id = #{body.pageId} AND status = 10");
if (page == null) {
    return response.json(404, "页面不存在或已下线", null);
}
var source = body.source == null ? 1 : body.source;
var ip = request.getClientIP();
var ua = request.getHeader("User-Agent") == null ? "" : request.getHeader("User-Agent");
var extraJson = body.extra == null ? null : JSON.stringify(body.extra);

db.insert("""
    INSERT INTO landing_lead(page_id, slug, phone, extra, source, client_ip, user_agent, submit_time)
    VALUES(#{page.id}, #{page.slug}, #{body.phone}, #{extraJson}, #{source}, #{ip}, #{ua}, NOW())
    """);
return { ok: true };

var stat = db.selectOne("""
    SELECT pv_count AS pv, uv_count AS uv
    FROM landing_page WHERE id = #{pageId}
    """);
var todayLeads = db.selectInt("""
    SELECT COUNT(*) FROM landing_lead
    WHERE page_id = #{pageId} AND submit_time >= CURRENT_DATE
    """);
stat.todayLeads = todayLeads;
return stat;
